// Valida el formulario de la guía y arma la fila del CSV. Sin datos válidos no se guarda nada.
const b = $json.body || {};
const limpia = (v, n) => String(v == null ? '' : v).replace(/[\r\n\t]+/g, ' ').trim().slice(0, n);
const nombre = limpia(b.nombre, 80), email = limpia(b.email, 120).toLowerCase(), empresa = limpia(b.empresa, 100), tel = limpia(b.tel, 30);
const idioma = b.idioma === 'en' ? 'en' : 'es', pagina = limpia(b.pagina, 120), resultado = limpia(b.resultado, 10);
const trampa = limpia(b.web, 50);
const valido = !trampa && b.acepto === true && nombre.length >= 2 && /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(email);
// Límite simple contra abuso: máximo 60 registros por hora y un correo una vez por día
const sd = $getWorkflowStaticData('global');
const ahora = Date.now();
sd.recientes = (sd.recientes || []).filter(r => ahora - r.t < 86400000);
const enHora = sd.recientes.filter(r => ahora - r.t < 3600000).length;
const repetido = sd.recientes.some(r => r.e === email);
let guardar = valido && enHora < 60 && !repetido;
if (guardar) sd.recientes.push({ t: ahora, e: email });
const csv = v => '"' + String(v).replace(/"/g, '""').replace(/^[=+\-@]/, "'$&") + '"';
const fecha = new Date().toLocaleString('sv-SE', { timeZone: 'America/Mexico_City' });
const linea = [fecha, nombre, email, empresa, tel, resultado, idioma, pagina].map(csv).join(',') + '\r\n';
return [{
  json: { ok: valido, guardar, nombre, email, empresa, tel, resultado, idioma, pagina, fecha,
    from: $env.NOTIFY_FROM || $env.GMAIL_USER || '', to: $env.NOTIFY_TO || '',
    subject: 'Nuevo contacto (checklist de TI): ' + nombre + (empresa ? ' · ' + empresa : ''),
    text: 'Descargó el checklist de TI en nodopera.com\n\nNombre: ' + nombre + '\nCorreo: ' + email + '\nEmpresa: ' + (empresa || '-') + '\nTeléfono: ' + (tel || '-') + '\nResultado: ' + (resultado || '-') + ' de 15\nIdioma: ' + idioma + '\nFecha: ' + fecha },
  binary: { data: { data: Buffer.from(linea, 'utf8').toString('base64'), mimeType: 'text/csv', fileName: 'guia.csv' } }
}];
